//! The data-format promise (0.9.0): `.harna/` written by any harna since
//! 0.3.0 reads with this one, migrates, and reads again; data written by a
//! newer harna is refused, never misread.
//!
//! Fixtures are harna's own `.harna/` at four releases (the map left out:
//! it is regenerated by `harna scan`, never migrated).

use std::path::{Path, PathBuf};

use harna_core::schema::store::Store;

const FIXTURES: &[&str] = &["v0_3_0", "v0_3_50", "v0_5_9", "v0_7_7"];

fn copy_dir(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for e in std::fs::read_dir(from).unwrap().flatten() {
        let p = e.path();
        let dst = to.join(e.file_name());
        if p.is_dir() {
            copy_dir(&p, &dst);
        } else {
            std::fs::copy(&p, &dst).unwrap();
        }
    }
}

fn scratch(name: &str) -> PathBuf {
    let root = std::env::temp_dir().join(format!("harna-formats-{name}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).unwrap();
    root
}

/// Every file of the store, through the store's own readers.
fn read_everything(store: &Store, root: &Path) -> anyhow::Result<()> {
    store.load_manifest()?;
    store.load_rules()?;
    store.load_effective_rules()?;
    store.load_templates()?;
    store.load_deferred()?;
    store.load_terms()?;
    store.load_non_goals()?;
    store.load_lessons()?;
    store.load_qualities()?;
    store.load_roadmap()?;
    store.load_acknowledged()?;
    store.load_commands()?;
    store.load_baselines()?;
    store.load_services()?;
    store.load_plugins()?;
    harna_core::enforcement::parity::list_events(store)?;
    harna_core::schema::journal::decisions::list(&root.join(".harna/decisions"))?;
    let _ = harna_core::schema::journal::handoff::load(store);
    Ok(())
}

#[test]
fn every_release_since_0_3_reads_migrates_and_reads_again() {
    let base = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/formats");
    for f in FIXTURES {
        let root = scratch(f);
        copy_dir(&base.join(f), &root);
        let store = Store::open(&root).unwrap();
        read_everything(&store, &root).unwrap_or_else(|e| panic!("{f} before migrate: {e:#}"));
        let reports = harna_core::schema::store::migrate::run(&root, &store, false)
            .unwrap_or_else(|e| panic!("{f} migrate: {e:#}"));
        assert!(!reports.is_empty(), "{f}: migrate reported nothing");
        read_everything(&store, &root).unwrap_or_else(|e| panic!("{f} after migrate: {e:#}"));
        let m = store.load_manifest().unwrap();
        assert!(!m.layers.is_empty(), "{f}: the manifest kept its layers");
        assert!(m.schema_version <= harna_core::SCHEMA_VERSION);
        // a second run finds nothing to do
        let again = harna_core::schema::store::migrate::run(&root, &store, false).unwrap();
        assert!(
            again.iter().all(|r| r.action == "already-current"),
            "{f}: migrate is idempotent: {again:?}"
        );
        let _ = std::fs::remove_dir_all(&root);
    }
}

#[test]
fn data_from_a_newer_harna_is_refused() {
    let base = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/formats");
    let root = scratch("future");
    copy_dir(&base.join("v0_7_7"), &root);
    let store = Store::open(&root).unwrap();
    let future = harna_core::SCHEMA_VERSION + 1;
    // a register
    std::fs::write(
        root.join(".harna/terms.toml"),
        format!("schema_version = {future}\n"),
    )
    .unwrap();
    assert!(store.load_terms().is_err(), "terms from the future");
    std::fs::remove_file(root.join(".harna/terms.toml")).unwrap();
    // a parity event
    std::fs::write(
        root.join(".harna/parity/later.toml"),
        format!(
            "schema_version = {future}\nid = \"later\"\ngeneration = 1\nbaseline_ref = \"HEAD\"\ncreated = \"x\"\nupdated = \"x\"\n"
        ),
    )
    .unwrap();
    assert!(harna_core::enforcement::parity::list_events(&store).is_err());
    std::fs::remove_file(root.join(".harna/parity/later.toml")).unwrap();
    // a contract
    std::fs::create_dir_all(root.join(".harna/contracts")).unwrap();
    std::fs::write(
        root.join(".harna/contracts/x.toml"),
        format!("schema_version = {future}\ncontainer = \"x\"\nversion = \"1.0.0\"\n"),
    )
    .unwrap();
    assert!(store.load_contract("x").is_err());
    // baseline data carries no stamp
    std::fs::write(
        root.join(".harna/contracts/y.toml"),
        "container = \"y\"\nversion = \"1.0.0\"\n",
    )
    .unwrap();
    let y = store.load_contract("y").unwrap().unwrap();
    store.save_contract(&y).unwrap();
    let raw = std::fs::read_to_string(root.join(".harna/contracts/y.toml")).unwrap();
    assert!(!raw.contains("schema_version"), "{raw}");
    let _ = std::fs::remove_dir_all(&root);
}

/// docs/FORMAT.md documents every entry the store knows, and harna's own
/// `.harna/` holds nothing else.
#[test]
fn the_format_page_lists_every_known_entry() {
    let doc = include_str!("../../../docs/FORMAT.md");
    for e in harna_core::schema::store::KNOWN {
        let shown = if e.contains('.') {
            format!("`{e}`")
        } else {
            format!("`{e}/`")
        };
        assert!(doc.contains(&shown), "docs/FORMAT.md does not list {shown}");
    }
    let own = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../.harna");
    for e in std::fs::read_dir(own).unwrap().flatten() {
        let n = e.file_name().to_string_lossy().to_string();
        assert!(
            n.starts_with('.') || harna_core::schema::store::KNOWN.contains(&n.as_str()),
            "harna's own .harna/ holds `{n}`, which no reader knows"
        );
    }
}
